    marks = [(r + c, v) for r, row in enumerate(grid)
             for c, v in enumerate(row) if v]

    # The colors repeat along anti-diagonals. Find the shortest cyclic
    # sequence compatible with every marked cell.
    for p in range(1, h + w):
        seq = {}
        for s, v in marks:
            k = s % p
            if k in seq and seq[k] != v:
                break
            seq[k] = v
        else:
            if len(seq) == p:
                return [[seq[(r + c) % p] for c in range(w)] for r in range(h)]

    # If the period has unmarked phases, infer them from the cyclic order
    # of the known phases, extending the shortest consistent pattern.
    p = max(s for s, _ in marks) + 1
    seq = {}
    for s, v in marks:
        seq[s % p] = v
    for k in range(p):
        if k not in seq:
            known = sorted(seq)
            before = [x for x in known if x < k]
            after = [x for x in known if x > k]
            seq[k] = seq[before[-1] if before else after[-1]]
    return [[seq[(r + c) % p] for c in range(w)] for r in range(h)]
